//! Actions-only original own normalized URI/current native auth DATA capture.
//! No RPC ID/socket/readiness/WRITE grant or original library execution.
#[path="im_send_identity_budget_tests.rs"]
mod budget;
use super::*;
#[test]fn im_sender_current_own_uri_is_normalized_login_identity_not_uid_phone_or_returned_mainaccount(){let(mut rpc,who,scope)=current_native();let next=rpc.next_id;let count=rpc.pending.len();let identity=rpc.send_identity().unwrap();assert_eq!(identity.uri_for(&who,&scope),Some(b"[username:fixture-user@fixture.invalid]".as_slice()));assert_eq!(identity.token_for(&who,&scope),Some(b"fixture-returned-auth-token".as_slice()));let fields=identity.statistics_for(&who,&scope,b"86").unwrap();assert_eq!(fields[0].key,b"Statistics.AppId");assert_eq!(fields[0].value,b"fixture-app-id");assert_eq!(fields[1].value,b"fixture-domain-id");assert_eq!(fields[2].value,b"86");assert!(identity.uri_for(&who,&scope).unwrap()!=b"fixture-returned-user");assert_eq!(rpc.next_id,next);assert_eq!(rpc.pending.len(),count);rpc.close();assert!(!identity.matches(&who,&scope));}
#[test]fn im_sender_sdk_prelogin_legacy_or_pending_login_never_produce_send_identity(){let mut rpc=ArcRpcSession::new(owner());assert!(rpc.send_identity().is_err());let(legacy,_,_)=authenticated();assert!(legacy.send_identity().is_err());rpc.claim_common_transport().unwrap();rpc.bind_common_identity(b"AccountEntry").unwrap();rpc.prepare_login(inputs(&[]),&[]).unwrap();assert!(rpc.send_identity().is_err());assert_eq!(rpc.phase(),ArcPhase::LoginPending);}
#[test]fn im_sender_foreign_owner_scope_revocation_and_logout_keep_sealed_identity_invalid(){let(mut rpc,who,scope)=current_native();let identity=rpc.send_identity().unwrap();assert!(identity.uri_for(&owner(),&scope).is_none());assert!(identity.token_for(&who,&RpcConnectionScope::fresh()).is_none());assert!(identity.statistics_for(&owner(),&scope,b"").is_none());rpc.prepare_logout(&[]).unwrap();assert!(rpc.send_identity().is_err());scope.mark_session_revoked();assert!(!identity.matches(&who,&scope));assert!(scope.is_open());}
#[test]fn im_sender_retained_account_uri_data_is_redacted_and_original_close_wipes_source_snapshots(){let(mut rpc,who,scope)=current_native();let identity=rpc.send_identity().unwrap();let text=format!("{identity:?}");for private in ["fixture","username","URI","token"]{assert!(!text.contains(private));}assert!(rpc.login_uri.is_some());assert!(rpc.login_application.is_some()&&rpc.login_domain.is_some());rpc.close();assert!(rpc.login_uri.is_none()&&rpc.login_application.is_none()&&rpc.login_domain.is_none());assert!(identity.uri_for(&who,&scope).is_none());}
